def count_palindromic_substrings(s):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            is_pal = True
            left = i
            right = j
            while left < right:
                if s[left] != s[right]:
                    is_pal = False
                    break
                left += 1
                right -= 1
            if is_pal:
                count += 1
    return count

print(count_palindromic_substrings('aaa'))

